INSERT INTO directions(id,name) VALUES(1,'Direktor o''rinbosari');
INSERT INTO directions(id,name) VALUES(3,'Tarbiyachi');
INSERT INTO directions(id,name) VALUES(4,'Yordamchi-tarbiyachi');
INSERT INTO directions(id,name) VALUES(5,'Jismoniy tarbiyachi');
INSERT INTO directions(id,name) VALUES(6,'Musiqa tarbiyachisi');
INSERT INTO questions(id,direction_id,text,answer) VALUES(1,1,'1.	Директор ўринбосари учун боланинг ривожланиш соҳаларини билиш нима учун муҳим?','Директор ўринбосари таълим-тарбия жараёнини ташкил этиш, педагогларга методик ёрдам кўрсатиш ва таълим сифати мониторингини олиб боришда иштирок этади. Шунинг учун у боланинг ривожланиш соҳалари ўзаро қандай боғлиқлигини билиши ва педагогларнинг фаолиятини шу асосда таҳлил қила олиши керак.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(2,1,'2.	Mashg‘ulot vaqtida bolaning hayoti yoki sog‘lig‘iga xavf tug‘dirishi mumkin bo‘lgan holatni direktor o‘rinbosari aniqladi. Tarbiyachi esa mashg‘ulotni to‘xtatmaslikni so‘radi. Direktor o‘rinbosari qanday yo‘l tutishi kerak?','Birinchi navbatda bolaning hayoti va sog‘lig‘ini himoya qilish chorasi ko‘riladi. Xavfli holat bartaraf etiladi, zarurat bo‘lsa tibbiy yordam tashkil qilinadi, holat tegishli tartibda rasmiylashtiriladi va sabablar o‘rganiladi. Ta’lim-tarbiya jarayonining davom ettirilishi bolaning xavfsizligidan ustun qo‘yilmaydi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(3,1,'3.	Tarbiyachi mashg‘ulotlarni amalda o‘tkazayotgan bo‘lsa-da, ta’lim-tarbiya jarayoniga oid hujjatlarni muntazam ravishda talabga muvofiq yuritmayapti. Direktor o‘rinbosari qanday choralar ko‘rishi kerak?','Holatni aniqlaydi, hujjatlarning qaysi talablarga mos kelmayotganini belgilaydi, pedagogga metodik ko‘rsatma beradi va kamchiliklarni bartaraf etish muddatini belgilaydi. Kamchilik takrorlansa, masalani direktor huzuriga kiritadi va xodimning mehnat vazifalarini bajarishi bo‘yicha belgilangan tartibda chora ko‘rilishiga asos yaratadi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(4,1,'4.	“Ilk qadam” davlat o‘quv dasturi bilan tashkilotning variativ dasturi o‘rtasidagi huquqiy munosabat qanday?','Davlat o‘quv dasturi variativ o‘quv dasturlarini yaratishda majburiy tayanch hujjat hisoblanadi. Demak, variativ dastur davlat o‘quv dasturining asosiy talablariga zid bo‘lishi mumkin emas.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(6,1,'6.	Rivojlanishida jismoniy yoki ruhiy xususiyatlari bo‘lgan bola guruhga qabul qilingan. Tarbiyachi unga umumiy mashg‘ulotni moslashtirmasdan olib bormoqda. Direktor o‘rinbosari qanday vazifani bajaradi?','Bolaning individual rivojlanish ehtiyojlarini hisobga olgan holda ta’lim-tarbiya jarayonini tashkil etish bo‘yicha pedagogga metodik yordam ko‘rsatadi. Zarur hollarda tegishli mutaxassislar bilan hamkorlikni tashkil qiladi va bola uchun moslashtirilgan ta’lim yo‘nalishlaridan foydalanilishini nazorat qiladi. Inklyuziv ta’lim va rivojlanishida turli xususiyatlari bo‘lgan bolalar uchun moslashtirilgan dasturlarni joriy etish maktabgacha ta’lim tizimini rivojlantirishning belgilangan yo‘nalishlaridan biridir.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(7,1,'7.	Боланинг ривожланиш соҳаларини алоҳида режалаштириш билан интеграциялашган ҳолда режалаштириш ўртасида қандай фарқ бор?','Алоҳида режалаштиришда ҳар бир ривожланиш соҳаси бўйича мақсадлар белгиланади. Интеграциялашган ёндашувда эса битта фаолият орқали бир нечта ривожланиш соҳаси биргаликда қамраб олинади. Масалан, «Баҳор» мавзусида бола табиатни кузатади, янги сўзларни ўрганади, санайди, мулоқот қилади ва расм чизади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(8,1,'8.	Директор ўринбосари тарбиячининг ривожланиш соҳалари бўйича ишини қандай баҳолаши керак?','Фақат режа ва ҳужжатларни текшириш билан чекланмаслиги керак. Машғулотни кузатиши, болаларнинг фаол иштирокини таҳлил қилиши, ривожлантирувчи муҳитни ўрганиши ва қўлланилаётган усуллар боланинг ёши ҳамда индивидуал эҳтиёжларига мослигини аниқлаши керак.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(9,1,'9.	Жисмоний ривожланиш ва соғлом турмуш тарзи соҳаси бўйича директор ўринбосари нималарни назорат қилиши лозим?','Болаларнинг ҳаракат фаоллиги, кун тартиби, шахсий гигиена, овқатланиш маданияти, хавфсизлиги ва жисмоний фаолият учун яратилган шароитларга эътибор қаратиши лозим. Бунда фақат ҳужжат эмас, амалиётдаги ҳолат ҳам ўрганилади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(13,3,'O‘zbekiston Respublikasining "Maktabgacha ta''lim va tarbiya to‘g‘risida"gi Qonuniga muvofiq, tarbiyachining asosiy majburiyatlari nimakardan iborat?','Qonunning 44-moddasiga ko‘ra, tarbiyachi: bolalarning hayoti va salomatligini muhofaza qilish, "Ilk qadam milliy " Davlat o‘quv dasturini bajarish, bolalarga nisbatan har qanday jismoniy va ruhiy tazyiqqa yo‘l qo‘ymaslik, kasbiy etika qoidalariga rioya qilish, ota-onalar bilan hamkorlik qilish hamda malakasini muntazam oshirib borishga majbur.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(14,3,'Maktabgacha ta’lim va tarbiyaning Davlat standarti ("Ilk Qadam" dasturi) bo‘yicha bola rivojlanishining 5 ta asosiy sohasi qaysilar?','1.	Jismoniy rivojlanish va sog‘lom turmush tarzining shakllanishi.INSERT INTO questions(id,direction_id,text,answer) VALUES(10,1,'Kompyuterning asosiy qismlari qaysilar?','Monitor, tizim bloki, klaviatura, sichqoncha. Qo''shimcha qurilmalar: printer, skaner, karnay, veb-kamera.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(32,3,'Yangi papka qanday yaratiladi?','Bo''sh joyda sichqonchaning o''ng tugmasini bosish → "Создать/New" → "Папка/Folder" → nom berish.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(15,3,'MTTda xavfsizlik va sanitariya normativlari (SanPin) bo‘yicha bolalarni sayrga olib chiqish talablari qanday?','Bolalar kuniga 2 marta (ertalab va tushlikdan so‘ng) sayrga olib chiqiladi. Sayr vaqti ob-havoga qarab belgilanadi (muntazam ravishda -15°C dan past haroratda yoki kuchli shamolda qisqartiriladi/bekor qilinadi). Sayr maydonchasi oldindan begona buyumlar va xavflardan holi qilinishi, tarbiyachi bolalarni doimiy vizual nazoratda tutishi shart.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(16,3,'«Илк қадам» давлат ўқув дастурида болага йўналтирилган ёндашув деганда нима тушунилади?','Ҳар бир боланинг ёши, қизиқиши, қобилияти, эҳтиёжи ва индивидуал ривожланиш суръатини ҳисобга олган ҳолда таълим-тарбия жараёнини ташкил этиш тушунилади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(18,3,'Боланинг ривожланишини кузатиш билан уни баҳолаш ўртасида қандай фарқ бор?','Кузатиш — боланинг ҳаракатлари, қизиқишлари ва ривожланишидаги ўзгаришлар ҳақида маълумот тўплаш. Баҳолаш эса шу маълумотларни таҳлил қилиб, болага қандай педагогик ёрдам кераклигини аниқлаш жараёнидир.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(19,3,'Инклюзив таълим шароитида тарбиячининг асосий вазифаси нимадан иборат?','Барча болалар учун тенг иштирок имкониятини яратиш, индивидуал эҳтиёжларни ҳисобга олиш, зарур мослаштиришларни амалга ошириш ва мутахассислар ҳамда ота-оналар билан ҳамкорлик қилиш.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(20,3,'Мактабгача ёшдаги болаларда танқидий фикрлаш қандай ривожлантирилади?','Муаммоли вазиятлар яратиш, очиқ саволлар бериш, тахмин қилиш, таққослаш, сабаб ва оқибатни аниқлаш ҳамда мустақил ечим топишга ундаш орқали ривожлантирилади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(21,3,'Мактабгача таълимда ўйин фаолияти нима учун муҳим ҳисобланади?','Ўйин боланинг нутқи, тафаккури, тасаввури, ижтимоий муносабатлари, мустақиллиги ва ҳиссий ривожланишини қўллаб-қувватлайди.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(23,3,'«Илк қадам» давлат ўқув дастурининг асосий вазифаси нимадан иборат?','Боланинг мактабгача ёш давридаги ривожланишини тизимли қўллаб-қувватлаш, таълим-тарбия жараёнини боланинг эҳтиёж ва имкониятларига мос ташкил этиш ҳамда мактаб таълимига тайёрлашдан иборат.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(24,3,'Давлат стандарти билан «Илк қадам» дастури ўртасида қандай фарқ бор?','Давлат стандарти мактабгача таълимга қўйиладиган умумий талаблар ва меъёрларни белгилайди, давлат ўқув дастури эса шу талабларни таълим-тарбия жараёнида амалга ошириш мазмуни ва ёндашувларини белгилайди. 802-сон қарорда давлат стандарти таркибига болалар ривожланишига қўйиладиган давлат талаблари ва давлат ўқув дастури киритилган.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(25,3,'Тарбиячи «Илк қадам» дастурини амалиётда қандай қўллайди?','Ривожланиш соҳалари ва кутилаётган натижаларни ҳисобга олиб, болаларнинг ёши, қизиқиши ва индивидуал хусусиятларига мос фаолиятларни режалаштиради ва амалга оширади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(26,3,'Боланинг индивидуал ривожланишини қандай аниқлайсиз?','Мунтазам кузатув, суҳбат, амалий фаолият ва боланинг мустақил ҳаракатларини таҳлил қилиш орқали аниқлайман.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(28,3,'Ривожлантирувчи муҳит деганда нимани тушунасиз?','Боланинг мустақил танлаши, ҳаракат қилиши, мулоқот қилиши, ижод қилиши ва янги билимни тажриба орқали эгаллаши учун яратилган хавфсиз ва педагогик жиҳатдан мақсадли муҳит.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(29,3,'Ривожланиш марказларида тарбиячининг роли қандай?','Тарбиячи марказдаги фаолиятни мақсадли ташкил этади, болаларни кузатади, зарур пайтда йўналтиради ва мустақил фаолият учун шароит яратади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(30,3,'Интеграцияланган машғулот нима?','Бир фаолият жараёнида бир нечта ривожланиш соҳаларининг ўзаро боғлиқ ҳолда ривожлантирилишидир.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(31,3,'Машғулот режалаштиришда энг муҳим учта омилни айтинг.','Болаларнинг ёши ва индивидуал хусусиятлари, фаолиятнинг мақсади ва кутилаётган натижа, фаолиятни амалга ошириш усуллари ва шароитлари.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(17,3,'Tizim blokining vazifasi nima?','U kompyuterning "miyasi" hisoblanadi. Unda protsessor, xotira va qattiq disk joylashgan bo''lib, barcha hisob-kitoblar shu yerda bajariladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(22,3,'Operatsion tizim nima? Misollar keltiring.','Operatsion tizim kompyuterni boshqaradigan asosiy dastur. Misollar: Windows, Linux, macOS (telefonlarda Android, iOS).');
INSERT INTO questions(id,direction_id,text,answer) VALUES(27,3,'Fayl va papka (jild) nima?','Fayl – saqlangan ma''lumot (hujjat, rasm, video). Papka esa fayllarni tartibli saqlash uchun mo''ljallangan "quti"dir.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(81,4,'Yordamchi tarbiyachi qanday malaka talablariga javob berishi kerak?','O''rta ma''lumot va maktabgacha yoshdagi bolalarni tarbiyalash ishlari xususiyatlari bo''yicha maxsus tayyorgarlik. Amaliy ish staji talab qilinmaydi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(82,4,'Yordamchi tarbiyachi qanday bilimlarga ega bo''lishi shart?','Maktabgacha ta''lim davlat talablari mazmuni, pedagogika va psixologiya asoslari, defektologiya asoslari, yosh anatomiyasi va fiziologiyasi, bolalarni o''qitish va tarbiyalash shakllari hamda usullari, bolalar adabiyoti, bolalar taomlari turlari va tayyorlash texnologiyasi, bolalar jamoaviy o''yinlarini tashkil etish qoidalari, gigiyena asoslari, bolalar hayoti va sog''lig''ini muhofaza qilish qoidalari.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(33,3,'Давлат стандарти қандай асосий таркибий қисмларни қамраб олади?','Болалар ривожланишига қўйиладиган давлат талаблари, мактабгача таълим ташкилотининг давлат ўқув дастури, намунавий ўқув режаси ҳамда ташкилотларни жиҳозлаш меъёрларини қамраб олади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(34,3,'Давлат стандартига риоя этилишини назорат қилишдан мақсад нима?','Белгиланган талабларнинг бажарилиш даражасини аниқлаш, камчиликларни бартараф этиш ва таълим-тарбия сифатини таъминлаш.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(35,3,'Тарбиячи давлат талабларини кундалик ишида қандай амалга оширади?','Машғулотларни режалаштириш, болаларнинг ёш хусусиятларини ҳисобга олиш, ривожланиш марказларини ташкил этиш, хавфсиз муҳит яратиш ва болаларнинг ривожланишини кузатиш орқали амалга оширади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(36,3,'ЎРҚ-595-сон Қонуннинг асосий мақсади нима?','Мактабгача таълим ва тарбия соҳасидаги муносабатларни тартибга солиш, таълим-тарбияни ташкил этишнинг ҳуқуқий асосларини белгилаш ва болаларнинг таълим олиш ҳуқуқини таъминлаш.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(38,3,'Tаълим ташкилоти ота-оналар билан ҳамкорликда нималарга эътибор бериши керак?','Боланинг ривожланиши, соғлиғи, хавфсизлиги, хулқ-атвори ва таълим-тарбияси бўйича мунтазам ахборот алмашишга ҳамда ота-оналарнинг қонуний ҳуқуқларини ҳурмат қилишга.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(39,3,'Алоҳида таълим эҳтиёжлари бўлган болалар билан ишлашда қандай ёндашув қўлланилади?','Боланинг индивидуал эҳтиёжларини ҳисобга олиш, зарур педагогик ёрдам кўрсатиш, тегишли мутахассислар билан ҳамкорлик қилиш ва унинг таълим олиш имкониятини таъминлаш.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(40,3,'Jismoniy rivojlanish va sog‘lom turmush tarzining shakllanishi sohasi nimalarni qamrab oladi?','Bolaning harakat faolligi, asosiy harakat ko‘nikmalari, jismoniy sifatlari, shaxsiy gigiyena, sog‘lom turmush tarzi va xavfsiz xulq-atvor ko‘nikmalarini shakllantirishni qamrab oladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(41,3,'Jismoniy rivojlanish va sog‘lom turmush tarzining shakllanishi sohasi nimalarni qamrab oladi?','Bolaning harakat faolligi, asosiy harakat ko‘nikmalari, jismoniy sifatlari, shaxsiy gigiyena, sog‘lom turmush tarzi va xavfsiz xulq-atvor ko‘nikmalarini shakllantirishni qamrab oladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(43,3,'Ijtimoiy-hissiy rivojlanish sohasining asosiy mazmuni nimadan iborat?','Bolaning o‘z his-tuyg‘ularini anglash va boshqarishi, boshqa insonlarning hissiyotlarini tushunishi, tengdoshlari va kattalar bilan muloqot qilishi, ijtimoiy munosabatlarga kirishishi hamda ijobiy xulq-atvor ko‘nikmalarini shakllantirishdan iborat.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(44,3,'Nutq, muloqot, o‘qish va yozish malakalari sohasi faqat harf va so‘zlarni o‘rgatishdan iboratmi?','Yo‘q. Bu soha bolaning tinglash, tushunish, savollarga javob berish, o‘z fikrini og‘zaki ifodalash, muloqot qilish, lug‘at boyligini rivojlantirish, kitobga qiziqish va o‘qish-yozishga tayyorgarlik ko‘nikmalarini ham qamrab oladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(45,3,'Bilish jarayonining rivojlanishi sohasida bolaning qanday qobiliyatlari rivojlantiriladi?','Kuzatish, izlanish, taqqoslash, guruhlash, sanash, muammoni hal qilish, sabab-oqibat aloqalarini anglash, fazoviy va matematik tasavvurlar hamda atrof-muhit haqidagi bilimlar rivojlantiriladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(46,3,'Ijodiy rivojlanish sohasi qanday faoliyatlar orqali amalga oshiriladi?','Rasm chizish, bo‘yoqlar bilan ishlash, loy yoki boshqa materiallardan foydalanish, musiqa, raqs, dramatizatsiya, qurish-yasash va boshqa ijodiy faoliyatlar orqali amalga oshiriladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(48,3,'Боланинг ривожланишини кузатиш билан уни баҳолаш ўртасида қандай фарқ бор?','Кузатиш — боланинг кундалик фаолияти, хатти-ҳаракатлари ва кўникмаларини мунтазам ўрганиш жараёни. Баҳолаш эса тўпланган маълумотлар асосида боланинг ривожланишидаги ютуқлар ва қўллаб-қувватлашга муҳтож жиҳатларни аниқлашдир. Бу жараён болаларни бир-бири билан таққослаш ёки уларга салбий ёрлиқ қўйиш учун ишлатилмайди');
INSERT INTO questions(id,direction_id,text,answer) VALUES(49,3,'Боланинг ривожланиш харитаси нима учун юритилади?','Боланинг ривожланиш динамикасини кузатиш, эришган натижаларини қайд этиш ва кейинги таълимий вазифаларни белгилаш учун юритилади. У тарбиячига қайси кўникмаларни мустаҳкамлаш ва болага қандай ёрдам бериш кераклигини аниқлашга ёрдам беради.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(37,3,'Microsoft Word dasturi nima uchun kerak?','Matnli hujjatlar (ariza, hisobot, rejalar, bayonnoma) yaratish, tahrirlash va chop etish uchun.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(42,3,'Word''da matnni qanday saqlash mumkin?','"Fayl" → "Saqlash" yoki Ctrl+S tugmalari birikmasi orqali. Birinchi marta saqlashda fayl nomi va joyi tanlanadi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(47,3,'Microsoft PowerPoint dasturi nima uchun ishlatiladi?','Slaydlar (taqdimotlar) yaratish uchun. Tarbiyachi uni ota-onalar yig''ilishida yoki bolalarga ko''rgazmali material ko''rsatishda ishlatishi mumkin.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(83,4,'Yordamchi tarbiyachi bolalarning rivojlanishini qanday baholaydi?','Bolalarning xulqini o''rganadi, yurish-turishini kuzatadi, muvaffaqiyatlarini ma''naviy rag''batlantiradi hamda tarbiyachi va ota-onalar bilan birga ularning yutuqlari va mumkin bo''lgan muammolarini muhokama qiladi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(84,4,'Yordamchi tarbiyachi qanday tadbirlarni tashkil etishda qatnashadi?','Guruh va individual mashg''ulotlar, o''yinlar, sahnalashtirilgan tomoshalar, tabiatga sayohatlar va boshqa tadbirlarni tashkil etishda qatnashadi. Bu tadbirlar bolalarning aqliy va jismoniy rivojlanishiga, vatanparvarlik tuyg''usini va ona yurtga hamda milliy qadriyatlarga muhabbatni shakllantirishga, muloqot ko''nikmalarini rivojlantirishga qaratilgan.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(85,4,'Yordamchi tarbiyachi bolalarni sayr va sayohatlarga olib chiqishda qatnashadimi?','Ha, yordamchi tarbiyachi tarbiyachiga bolalarga qarashda yordam beradi hamda bolalarni o''yin maydonchalariga, muzeylarga, bog''larga va boshqa dam olish joylariga olib chiqishda ko''maklashadi.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(50,3,'«Илк қадам» давлат ўқув дастурининг асосий мақсади нимадан иборат ва тарбиячи бу мақсадга қандай эришади?','Дастурнинг асосий мақсади боланинг жисмоний, ижтимоий-ҳиссий, нутқий, билиш ва ижодий ривожланишини таъминлаш ҳамда унинг кейинги таълим босқичига тайёр бўлишига кўмаклашишдир. Тарбиячи болага тайёр билимларни бериш билангина чекланмайди, балки уни мустақил фикрлаш, изланиш, савол бериш, муаммоларни ҳал қилиш ва ўз фикрини ифодалашга йўналтиради.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(51,3,'Ривожлантирувчи муҳитни ташкил этишда боланинг мустақиллиги қандай таъминланади?','Материалларни бола мустақил олиши ва жойига қайтариши мумкин бўлган тарзда жойлаштириш, танлаш имконини бериш, фаолиятга аралашишни меъёрда сақлаш орқали таъминланади. Тарбиячи бола ўрнига вазифани бажармасдан, унга мустақил ечим топиш учун шароит яратади.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(5,1,'Kompyuter nima?','Kompyuter ma''lumotlarni qabul qiladigan, saqlaydigan, qayta ishlaydigan va natijani ko''rsatadigan elektron qurilmadir.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(52,3,'Excel dasturi nimaga mo''ljallangan?','Jadvallar bilan ishlash va hisob-kitoblar uchun. Masalan, bolalar davomati, ovqatlanish hisobi, ro''yxatlar.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(53,6,'Musiqa rahbari lavozimiga qanday malaka talablari qo''yiladi?','Kamida o''rta maxsus musiqiy ma''lumot; musiqa asboblaridan birini nota orqali mustaqil ijro eta olish; amaliy ish staji talab etilmaydi .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(54,6,'Musiqa rahbari qanday bilimlarga ega bo''lishi shart?','"Ilk va maktabgacha yoshdagi bolalarning rivojlanishiga qo''yiladigan Davlat talablari" hamda "Ilk qadam" davlat o''quv dasturi mazmuni; bolalarni maktabgacha tarbiyalash pedagogikasi va psixologiyasi asoslari; bolalar anatomiyasi va fiziologiyasi; musiqa nazariyasi, garmoniya, solfejio, musiqa tarixi; o''zbek, sharq va Yevropa mumtoz musiqa san''ati; vokal-xor ko''nikmalari .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(55,6,'Musiqa rahbarining asosiy lavozim majburiyatlariga nimalar kiradi?','Maktabgacha ta''lim tashkilotida musiqa mashg''ulotlarini tashkil etish; bolalarning musiqiy didini va dastlabki musiqiy savodini o''stirish; musiqiy layoqatini qobiliyat darajasiga ko''tarish; bolalar bilan jamoaviy va yakka tartibda faoliyat olib borish; bayram ertaliklarini tashkil etish; pedagoglar va ota-onalar bilan hamkorlik qilish .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(56,6,'Musiqa rahbari qanday ish hujjatlarini yuritishi shart?','Maktabgacha ta''lim agentligining tegishli buyrug''iga muvofiq musiqa rahbarining 5 ta ish hujjati yuritiladi: 07-01 "Davlat o''quv dasturi va metodik qo''llanmalar"; 07-02 "Oylik ish rejasi (Ish jurnali)"; 07-03 "Bolalar bilan yakka tartibda ishlash rejasi"; 07-04 "Ma''naviy-ma''rifiy tadbirlarni o''tkazish rejasi va ertaliklar ssenariylari"; 07-05 "Korreksion ritmik mashg''ulotlari rejasi" (ixtisoslashtirilgan tashkilotlar uchun) .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(57,6,'Musiqa rahbarining ish jurnali qanday bo''limlardan iborat?','Musiqa rahbarining ish jurnali quyidagi bo''limlardan iborat: musiqa rahbarining ish jadvali; musiqa mashg''ulotlarining istiqbol rejasi; musiqa rahbarining oylik ish rejasi; maktabgacha ta''lim tashkilotida bayram tadbirlarini o''tkazish siklogrammasi .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(58,6,'Musiqa rahbari o''quv yili davomida qanday metodik ishlarni taqdim etishi kerak?','Har bir o''quv yili davomida musiqa rahbari o''zining yangicha metodik ishlari va izlanishlari natijasini ochiq mashg''ulot yoki seminar tarzida pedagoglar va rahbariyat jamoasiga, shu bilan birga kuzatuv kengashi a''zolariga taqdim etishi ko''zda tutilgan.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(59,5,'Jismoniy tarbiya va sport yo''riqchisi lavozimiga qanday malaka talablari qo''yiladi?','Jismoniy tarbiya bo''yicha o''rta maxsus ma''lumot. Amaliy ish staji talab qilinmaydi .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(60,5,'Jismoniy tarbiya va sport yo''riqchisi qanday bilimlarga ega bo''lishi shart?','Maktabgacha ta''limga davlat talablari mazmuni; Xalq ta''limi vazirligining maktabgacha muassasalarda jismoniy tarbiya va bolalar sportini rivojlantirish masalalariga oid metodik, me''yoriy va yo''riqnoma hujjatlari; bolalarni maktabgacha tarbiyalash pedagogika va psixologiyasi asoslari; bolalarni jismoniy tarbiyalashning nazariya va amaliyoti asoslari; bolalar anatomiyasi va fiziologiyasi; sport-ommaviy tadbirlar o''tkazish tartibi; zamonaviy va xalq bolalar sport o''yinlari qoida va talablari .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(61,5,'Jismoniy tarbiya va sport yo''riqchisining asosiy majburiyatlaridan biri nima?','Mashg''ulotlar paytida bolalar sog''lig''i va xavfsizligiga javobgar bo''lish, o''zining kasbiy mahoratini uzluksiz takomillashtirish, maktabgacha muassasa xodimlari va ota-onalar orasida jismoniy tarbiya tashviqotini olib borish .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(62,5,'Maktabgacha ta''limda jismoniy tarbiya bo''yicha o''quv-tarbiyaviy faoliyat qanday hujjat asosida amalga oshiriladi?','O''zbekiston Respublikasining ilk va maktab yoshidagi bolalarni rivojlantirishga oid davlat talablari asosida amalga oshiriladi. Shuningdek, "Ilk qadam" davlat o''quv dasturi va Davlat standartlarida har bir yosh guruhi uchun belgilangan jismoniy tarbiya mashg''ulotlari mazmuni belgilab berilgan .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(63,5,'Jismoniy tarbiya yo''riqchisi ishida qanday asosiy tamoyilga rioya qilishi kerak?','Mashg''ulotlarni o''tkazishda tarbiyachi yoki jismoniy tarbiya yo''riqchisi vazifalarni aniq-ravshan bilishi, mashg''ulotni olib borishda izchillikka rioya qilishi, shuningdek bolalar yosh va individual xususiyatlarini hisobga olishi shart .');
INSERT INTO questions(id,direction_id,text,answer) VALUES(64,5,'Mashg''ulot vaqtida tarbiyachi yoki yo''riqchining asosiy vazifalaridan biri nima?','Mashg''ulot vaqtida bola organizmining dinamikasi va uning psixologiyasini nazorat qilish va e''tiborli bo''lish. Tarbiyachi yoki yo''riqchi qanchalik mashg''ulot davomida faol bo''lib, bolalarga e''tiborli bo''lsa, jismoniy tarbiya mashg''ulotidagi ta''lim va tarbiya jarayonining samaradorligi shunchalik darajada ko''tarilib boradi');
INSERT INTO questions(id,direction_id,text,answer) VALUES(65,4,'Ёрдамчи тарбиячи боланинг ривожланиш соҳаларини билиши нима учун зарур?','Ёрдамчи тарбиячи болалар билан кун давомида бевосита мулоқотда бўлади. Шунинг учун у боланинг жисмоний, ижтимоий-ҳиссий, нутқий, билиш ва ижодий ривожланишига мос муҳит яратишда тарбиячига кўмаклашиши керак. Унинг вазифаси фақат гуруҳ хоналарини тартибда сақлаш билан чекланмайди.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(86,4,'Yordamchi tarbiyachi bolalar salomatligini muhofaza qilish bo''yicha nimalarni bilishi shart?','Gigiyena asoslarini, bolalar hayoti va sog''lig''ini muhofaza qilish qoidalarini bilishi shart.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(66,4,'Ёрдамчи тарбиячи боланинг жисмоний ривожланиши ва соғлом турмуш тарзини қўллаб-қувватлашда қандай иштирок этади?','Болаларнинг кун тартибига риоя қилиши, шахсий гигиена қоидаларини бажариши, овқатланиш ва дам олиш жараёнида белгиланган тартибга амал қилишига кўмаклашади. Шу билан бирга, болалар учун хавфсиз ва тоза муҳитни таъминлашга эътибор беради.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(67,4,'Ёрдамчи тарбиячи боланинг ижтимоий-ҳиссий ривожланишига қандай таъсир кўрсатиши мумкин?','Бола билан ҳурматли мулоқот қилиш, уни тинглаш, ҳис-туйғуларини инобатга олиш, тенгдошлари билан мулоқот қилишга шароит яратиш орқали ижтимоий-ҳиссий ривожланишни қўллаб-қувватлайди.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(68,4,'Ёрдамчи тарбиячининг асосий вазифаси фақат гуруҳ хонасини тозалаш ва болаларга қарашдан иборатми?','Йўқ. Ёрдамчи тарбиячи гуруҳда санитария-гигиена талабларига риоя этилишини таъминлаш, болаларга кун тартиби жараёнларида кўмаклашиш, овқатланиш, сайр, дам олиш ва ўз-ўзига хизмат қилиш жараёнларида тарбиячига ёрдам бериш, болалар хавфсизлигини таъминлашда белгиланган вазифаларни бажариш каби мажбуриятларга эга.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(69,4,'Энг мураккаб вазият: ёрдамчи тарбиячи бир вақтнинг ўзида полга сув тўкилганини, бир бола йиғлаётганини ва бошқа бола эшик томон югураётганини кўрди. У қайси ҳаракатни биринчи бажариши керак?','Биринчи навбатда болалар ҳаёти ва хавфсизлигига бевосита таҳдид солаётган ҳолатни бартараф этиши керак. Яъни боланинг хавфли жойга чиқиб кетиши ёки жароҳат олишининг олдини олади. Шу билан бир вақтда имкон қадар тарбиячини хабардор қилади. Кейин йиғлаётган боланинг ҳолатига эътибор беради ва полдаги сувни зудлик билан бартараф этади. Бунда устуворлик — ҳаёт ва хавфсизлик → соғлиқ → санитария ва тартиб тамойили асосида ҳаракат қилишдир.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(70,4,'Ёрдамчи тарбиячининг асосий вазифаси нимадан иборат?','Ёрдамчи тарбиячи гуруҳда болалар учун хавфсиз, санитария-гигиена талабларига мос ва тартибли муҳитни таъминлашда тарбиячига кўмаклашади. Болаларнинг овқатланиши, кун тартиби, хоналар тозалиги, жиҳозларнинг тартибли сақланиши ва болалар хавфсизлигига оид белгиланган вазифаларни бажаради.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(71,4,'MTTda tarbiyalanuvchining hayoti va sog''lig''i uchun kim javobgar? Agar tarbiyachi xonada yo''qligida yordamchi tarbiyachi nazoratsiz qoldirgan bola jarohat olsangiz, qanday javobgarlik kelib chiqadi?','*"Maktabgacha ta''lim tashkilotida bolaning hayoti va sog''lig''i uchun tarbiyachi bilan birga yordamchi tarbiyachi ham teng javobgar hisoblanadi. Mehnat kodeksi va ichki mehnat tartib-qoidalariga ko''ra, bolani nazoratsiz qoldirish xizmat vazifasiga sovuqqonlik bilan qarash deb baholanadi. Oqibatiga qarab:INSERT INTO questions(id,direction_id,text,answer) VALUES(72,4,'SanPiN (Sanitariya qoidalari va me''yorlari) bo''yicha guruh xonasini shamollatish, namli tozalash va idishlarni yuvish tartibi qanday?',':"1. Shamollatish: Bolalar xonada bo''lmagan vaqtda (sayr, zalga tushganda yoki uxlash xonasiga o''tganda) kuniga kamida 2-3 marta amalga oshiriladi. Bolalar bor xonada keskin shamollatish (skvoznyak) qilish taqiqlanadi.INSERT INTO questions(id,direction_id,text,answer) VALUES(73,4,'Dezinfeksiyalovchi vositalar (xlorka va b.) qayerda saqlanishi kerak va eritma tayyorlashda adashmaslik uchun qoidangiz qanday?','"Dezinfeksiya vositalari bolalar qo me''li yetmaydigan, maxsus qulflanadigan javon yoki xonada saqlanishi shart. Erityotganda yo me''riqnoma bo''yicha aniq dozasiga amal qilaman (masalan, 10 litr suvga qancha tabletka/suyuqlik). Har bir ishlatiladigan idish ustida eritma konsentratsiyasi va tayyorlangan vaqti ko''rsatilgan markirovka (yorliq) bo''lishi shart."');
INSERT INTO questions(id,direction_id,text,answer) VALUES(74,4,'Болалар овқатланиши вақтида тарбиячи ёрдамчисининг энг муҳим вазифаси қайси?','Овқатланиш жараёнида санитария-гигиена ва хавфсизлик талабларига риоя этилишини таъминлашга кўмаклашиш');
INSERT INTO questions(id,direction_id,text,answer) VALUES(75,4,'“Maktabgacha taʼlim va tarbiya toʻgʻrisida”gi Qonunning asosiy maqsadi nima?','Maktabgacha taʼlim va tarbiya sohasidagi munosabatlarni tartibga solish.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(76,4,'Yordamchi tarbiyachi lavozim majburiyatlarining asosiy qismlarini ayting (malaka tavsiflariga koʻra).','Tarbiyachiga bolalarga qarashda yordam berish; oʻyinlar, ekskursiyalar, mashgʻulotlarda ishtirok etish; bolalarni ovqatlantirish va choʻmiltirishni tashkil etish; oʻziga-oʻzi xizmat koʻnikmalarini oʻrgatish; bolalarning xulq-atvorini kuzatish va baholash.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(77,4,'Inklyuziv taʼlim va tarbiya nima deb tushuniladi?','Bolalarning alohida taʼlim olish ehtiyojlari va individual imkoniyatlarini hisobga olgan holda teng imkoniyatlarni taʼminlaydigan jarayon.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(78,4,'Professional etika qoidalari nima va nima uchun muhim?','Pedagogning kasbiy majburiyatlarini bajarishdagi odob-axloq normalari; bolalar va ota-onalar ishonchini saqlash uchun.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(79,4,'Bolaning individual xususiyatlarini hisobga olmaslik qanday oqibatlarga olib keladi?','Rivojlanish kechikishi, psixologik travma, ota-ona shikoyatlari, qonuniy javobgarlik');
INSERT INTO questions(id,direction_id,text,answer) VALUES(80,4,'Agar sizning harakatingiz qonunga zid deb topilsa, oqibatlari nima?','Intizomiy jazo, mehnat shartnomasini bekor qilish, maʼmuriy yoki jinoiy javobgarlik, pedagogik faoliyatga taqiq.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(87,4,'Maktabgacha ta''lim tashkilotlarida bolalar salomatligini muhofaza qilish nimalarni o''z ichiga oladi?','Birinchi yordam ko''rsatish; o''quv-tarbiya yuklamasini me''yorida belgilash; sog''lom turmush tarzi ko''nikmalarini targ''ib qilish va o''rgatish; sog''liqni mustahkamlash tadbirlarini tashkil etish; kun tartibiga rioya qilish; sog''lom ovqatlanishni tashkil etish; jismoniy tarbiya bilan shug''ullanish uchun sharoit yaratish.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(88,4,'Yordamchi tarbiyachi bolalar xavfsizligi uchun qanday javobgarlikni o''z zimmasiga oladi?','Bolalar maktabgacha ta''lim tashkiloti hududida bo''lgan butun vaqt davomida ularning xavfsizligi uchun javobgar.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(89,4,'Bola yangi guruhga moslasholmayapti, doim yig''laydi. Sizning harakatlaringiz?','Bolaga ko''proq e''tibor va mehr ko''rsataman, uni tinchlantiraman. Tarbiyachi bilan birgalikda bolaning qiziqishlarini aniqlaymiz va o''yinga jalb qilamiz. Ota-onalar bilan suhbatlashib, bolaning uy sharoitidagi odatlarini o''rganamiz. Moslashuv davrini bosqichma-bosqich o''tkazamiz.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(90,4,'3 yoshli bola guruhda doimiy ravishda boshqa bolalarni tishlaydi. Sizning harakatlaringiz?','Darhol bolani ajratish va jabrlanuvchiga birinchi yordam ko''rsatish; tishlagan bolaning his-tuyg''ularini tan olish va xavfsiz alternativ usul taklif qilish; tarbiyachiga xabar berish va ota-onalar bilan birgalikda sababni aniqlash; guruhda ijobiy munosabat modelini shakllantirish.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(91,4,'Bola uyqu vaqtida uxlashni xohlamaydi va boshqa bolalarni ham uyg''otmoqda. Sizning harakatlaringiz?','Tinch ovozda bolaga yaqinlashaman, uni boshqa bolalarga xalaqit bermasdan yotishga ko''ndiraman. Sokin musiqa yoki ertak aytish kabi tinchlantiruvchi usullardan foydalanaman. Agar davom etsa, bolani ajratib, alohida tinch joyda kuzataman.');
INSERT INTO questions(id,direction_id,text,answer) VALUES(92,4,'Yordamchi tarbiyachi bolalarni cho''miltirishni tashkil qiladimi?','Ha, yordamchi tarbiyachi bolalarni ovqatlantirishni va cho''miltirishni tashkil qiladi va amalga oshiradi, ularni o''ziga o''zi xizmat ko''rsatish ko''nikmalariga o''rgatadi');
INSERT INTO questions(id,direction_id,text,answer) VALUES(93,4,'Yordamchi tarbiyachi maktabgacha yoshdagi bolalarni o''qitish va tarbiyalashning qanday shakl va metodlarini bilishi lozim?','Maktabgacha yoshdagi bolalarni o''qitish va tarbiyalash shakl va metodlarini, jumladan maktabgacha yoshdagi bolalarga tilni, matematikani, tabiatshunoslikni, tasviriy san''atni o''qitish metodikalarini, mehnat ta''limini, musiqiy va jismoniy tarbiyani o''rgatishni bilishi lozim');
INSERT INTO questions(id,direction_id,text,answer) VALUES(94,4,'Yordamchi tarbiyachi bolalar adabiyoti va bolalar ovqatlari bo''yicha qanday bilimlarga ega bo''lishi kerak?','Bolalar adabiyotini, bolalar o''qitilayotgan tilning grammatik tuzilishi va so''z tarkibini, bolalar ovqatlarining turlarini, retseptlarini va tayyorlash texnologiyalarini bilishi lozim');
INSERT INTO questions(id,direction_id,text,answer) VALUES(95,4,'Yordamchi tarbiyachi qanday qoidalarni bilishi shart?','Maktabgacha yoshdagi bolalarning ommaviy o''yinlarini tashkil qilish qoidalarini, gigiyena asoslarini, bolalar hayoti va sog''lig''ini muhofaza qilish qoidalarini bilishi shart');
INSERT INTO questions(id,direction_id,text,answer) VALUES(96,4,'Yordamchi tarbiyachi ishga qabul qilinganda qanday hujjat asosida faoliyat yuritadi?','Lavozim yo''riqnomasi va malaka tavsiflarida belgilangan talablar asosida faoliyat yuritadi. Malaka tavsiflari O''zbekiston Respublikasi Xalq ta''limi xodimlari asosiy lavozimlarining malaka tavsiflarini tasdiqlash to''g''risidagi hujjat bilan belgilangan');
INSERT INTO questions(id,direction_id,text,answer) VALUES(97,4,'Yordamchi tarbiyachi bolalarning ommaviy o''yinlarini tashkil qilishda qanday qoidalarga rioya qilishi kerak?','Maktabgacha yoshdagi bolalarning ommaviy o''yinlarini tashkil qilish qoidalariga rioya qilishi, o''yinlar bolalarning yoshiga mos bo''lishi, xavfsiz o''yinchoqlardan foydalanish, bolalar o''rtasida ziddiyatsiz muloqot muhitini yaratish kerak');
INSERT INTO questions(id,direction_id,text,answer) VALUES(98,4,'Yordamchi tarbiyachi bolalarda qanday ko''nikmalarni shakllantirishga yordam beradi?','Bolalarning yoshini, o''z-o''zini boshqarishlarini, mehnat muhofazasi talablariga rioya etilishini hisobga olgan holda ularni sanitariya-gigiyenik ko''nikmalarini ta''minlashga yordam beradi');
INSERT INTO questions(id,direction_id,text,answer) VALUES(99,4,'Sizningcha, tarbiyachi yordamchisi uchun eng muhim ko‘nikma nima va nima uchun?','Eng muhim ko‘nikma — bolalarning ehtiyojlarini tez payqash va ularga o‘z vaqtida javob berish. Chunki bu lavozimda bolalar bilan bevosita ishlash, ularning xavfsizligi va farovonligini ta’minlash talab etiladi. Tez va to‘g‘ri qaror qabul qilish ko‘nikmasi bo‘lmasa, bolalarning sog‘lig‘i va xavfsizligiga xavf tug‘ilishi mumkin.');
