INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(51,11,1,'Jismoniy tarbiya va sport yo''riqchisi qanday bilimlarga ega bo''lishi shart?','Maktabgacha ta''limga davlat talablari mazmuni; Xalq ta''limi vazirligining maktabgacha muassasalarda jismoniy tarbiya va bolalar sportini rivojlantirish masalalariga oid metodik, me''yoriy va yo''riqnoma hujjatlari; bolalarni maktabgacha tarbiyalash pedagogika va psixologiyasi asoslari; bolalarni jismoniy tarbiyalashning nazariya va amaliyoti asoslari; bolalar anatomiyasi va fiziologiyasi; sport-ommaviy tadbirlar o''tkazish tartibi; zamonaviy va xalq bolalar sport o''yinlari qoida va talablari .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(52,11,2,'Jismoniy tarbiya va sport yo''riqchisi lavozimiga qanday malaka talablari qo''yiladi?','Jismoniy tarbiya bo''yicha o''rta maxsus ma''lumot. Amaliy ish staji talab qilinmaydi .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(53,11,3,'Jismoniy tarbiya yo''riqchisi ishida qanday asosiy tamoyilga rioya qilishi kerak?','Mashg''ulotlarni o''tkazishda tarbiyachi yoki jismoniy tarbiya yo''riqchisi vazifalarni aniq-ravshan bilishi, mashg''ulotni olib borishda izchillikka rioya qilishi, shuningdek bolalar yosh va individual xususiyatlarini hisobga olishi shart .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(54,11,4,'Mashg''ulot vaqtida tarbiyachi yoki yo''riqchining asosiy vazifalaridan biri nima?','Mashg''ulot vaqtida bola organizmining dinamikasi va uning psixologiyasini nazorat qilish va e''tiborli bo''lish. Tarbiyachi yoki yo''riqchi qanchalik mashg''ulot davomida faol bo''lib, bolalarga e''tiborli bo''lsa, jismoniy tarbiya mashg''ulotidagi ta''lim va tarbiya jarayonining samaradorligi shunchalik darajada ko''tarilib boradi','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(55,11,5,'Jismoniy tarbiya va sport yo''riqchisining asosiy majburiyatlaridan biri nima?','Mashg''ulotlar paytida bolalar sog''lig''i va xavfsizligiga javobgar bo''lish, o''zining kasbiy mahoratini uzluksiz takomillashtirish, maktabgacha muassasa xodimlari va ota-onalar orasida jismoniy tarbiya tashviqotini olib borish .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(56,12,1,'Musiqa rahbarining ish jurnali qanday bo''limlardan iborat?','Musiqa rahbarining ish jurnali quyidagi bo''limlardan iborat: musiqa rahbarining ish jadvali; musiqa mashg''ulotlarining istiqbol rejasi; musiqa rahbarining oylik ish rejasi; maktabgacha ta''lim tashkilotida bayram tadbirlarini o''tkazish siklogrammasi .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(58,12,3,'Musiqa rahbari qanday ish hujjatlarini yuritishi shart?','Maktabgacha ta''lim agentligining tegishli buyrug''iga muvofiq musiqa rahbarining 5 ta ish hujjati yuritiladi: 07-01 "Davlat o''quv dasturi va metodik qo''llanmalar"; 07-02 "Oylik ish rejasi (Ish jurnali)"; 07-03 "Bolalar bilan yakka tartibda ishlash rejasi"; 07-04 "Ma''naviy-ma''rifiy tadbirlarni o''tkazish rejasi va ertaliklar ssenariylari"; 07-05 "Korreksion ritmik mashg''ulotlari rejasi" (ixtisoslashtirilgan tashkilotlar uchun) .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(59,12,4,'Musiqa rahbari qanday bilimlarga ega bo''lishi shart?','"Ilk va maktabgacha yoshdagi bolalarning rivojlanishiga qo''yiladigan Davlat talablari" hamda "Ilk qadam" davlat o''quv dasturi mazmuni; bolalarni maktabgacha tarbiyalash pedagogikasi va psixologiyasi asoslari; bolalar anatomiyasi va fiziologiyasi; musiqa nazariyasi, garmoniya, solfejio, musiqa tarixi; o''zbek, sharq va Yevropa mumtoz musiqa san''ati; vokal-xor ko''nikmalari .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(60,12,5,'Musiqa rahbari lavozimiga qanday malaka talablari qo''yiladi?','Kamida o''rta maxsus musiqiy ma''lumot; musiqa asboblaridan birini nota orqali mustaqil ijro eta olish; amaliy ish staji talab etilmaydi .','waiting');
INSERT INTO asked(id,participant_id,ord,text,answer,status) VALUES(57,12,2,'Musiqa rahbari o''quv yili davomida qanday metodik ishlarni taqdim etishi kerak?','Har bir o''quv yili davomida musiqa rahbari o''zining yangicha metodik ishlari va izlanishlari natijasini ochiq mashg''ulot yoki seminar tarzida pedagoglar va rahbariyat jamoasiga, shu bilan birga kuzatuv kengashi a''zolariga taqdim etishi ko''zda tutilgan.','current');
